40:   validate(content: string): ValidationResult {
41:     const results: string[] = [];
42:     const lines = content.split('\n');
43: 
44:     if (lines.length === 0) return { valid: true };
45: 
46:     lines.forEach((line, index) => {
47:       if (line.trim().length === 0 && index < lines.length - 1) {
48:         results.push(`Line ${index + 1} is empty`);
49:       } else if (line.trim().length === 0 && index === lines.length - 1) {
50:         // Last line can be empty if it's just a trailing newline
51:       } else {
52:         const parts = line.split(',');
53:         if (parts.length !== this.expectedColumnCount) {
54:           results.push(`Line ${index + 1} has ${parts.length} columns, expected ${this.expectedColumnCount}`);
55:         }
56:       }
57:     });
